class User:
    def __init__(self, id: int, username: str, password: str, interests: str = '', reading_habits: str = ''):
        self.id = id
        self.username = username
        self.password = password
        self.interests = interests
        self.reading_habits = reading_habits

    def add_interest(self, interest: str):
        if interest not in self.interests:
            self.interests += ',' + interest

    def update_reading_habits(self, article: 'Article'):
        if article.id not in self.reading_habits:
            self.reading_habits += ',' + str(article.id)

    @classmethod
    def get_user(cls, user_id: int, db_manager: DatabaseManager) -> 'User':
        user_data = db_manager.get_user(user_id)
        return cls(user_id, user_data['username'], user_data['password'], user_data['interests'], user_data['reading_habits'])

    def save_to_db(self, db_manager: DatabaseManager):
        db_manager.insert_user(self.__dict__)

