from django.shortcuts import render
from django.http import JsonResponse
from django.views import View
from .models import Content
from django.contrib.auth import authenticate, login, logout

class ContentView(View):
    """
    ContentView handles the creation of new content and content retrieval.
    """

    def post(self, request):
        """
        Handle POST requests.
        """
        data = request.POST
        title = data.get('title')
        description = data.get('description')
        category = data.get('category')
        creator_id = data.get('creator_id')

        if not all([title, description, category, creator_id]):
            return JsonResponse({'error': 'Missing required information.'}, status=400)

        try:
            creator = User.objects.get(id=creator_id)
        except User.DoesNotExist:
            return JsonResponse({'error': 'Creator not found.'}, status=404)

        content = Content.objects.create(title=title, description=description, category=category, creator=creator)
        content.save()

        return JsonResponse({'message': 'Content created successfully.'}, status=201)

    def get(self, request):
        """
        Handle GET requests.
        """
        content_id = request.GET.get('content_id')

        if content_id:
            try:
                content = Content.objects.get(id=content_id)
                return JsonResponse({'title': content.title, 'description': content.description, 'category': content.category, 'creator': content.creator.id}, status=200)
            except Content.DoesNotExist:
                return JsonResponse({'error': 'Content not found.'}, status=404)
        else:
            contents = Content.objects.all()
            return JsonResponse([{'id': content.id, 'title': content.title, 'description': content.description, 'category': content.category, 'creator': content.creator.id} for content in contents], status=200)

    def delete(self, request):
        """
        Handle DELETE requests.
        """
        content_id = request.GET.get('content_id')

        if content_id:
            try:
                content = Content.objects.get(id=content_id)
                content.delete()
                return JsonResponse({'message': 'Content deleted successfully.'}, status=200)
            except Content.DoesNotExist:
                return JsonResponse({'error': 'Content not found.'}, status=404)
        else:
            return JsonResponse({'error': 'Missing required information.'}, status=400)
