    model = Startup
    form_class = StartupForm
    template_name = 'startups/startup_form.html'

    def form_valid(self, form):
        form.save()
        return redirect('startup_list')

class StartupUpdateView(UpdateView):
    model = Startup
    form_class = StartupForm
    template_name = 'startups/startup_form.html'

    def form_valid(self, form):
        form.save()
        return redirect('startup_list')

