## game.py

import curses
from level import Level
from spaceship import Spaceship
from invader import Invader
from bullet import Bullet

class Game:
    def __init__(self, stdscr):
        self.stdscr = stdscr
        self.score = 0
        self.level = 1
        self.spaceship = Spaceship(0, 0)
        self.invaders = Level(self.level).generate_invaders()
        self.bullets = []

    def start(self):
        self.stdscr.clear()
        self.stdscr.addstr(0, 0, f"Level: {self.level}")
        self.stdscr.addstr(1, 0, f"Score: {self.score}")
        self.stdscr.refresh()

    def pause(self):
        self.stdscr.addstr(2, 0, "Game Paused")
        self.stdscr.refresh()

    def resume(self):
        self.stdscr.clear()
        self.stdscr.addstr(0, 0, f"Level: {self.level}")
        self.stdscr.addstr(1, 0, f"Score: {self.score}")
        self.stdscr.refresh()

    def end(self):
        self.stdscr.clear()
        self.stdscr.addstr(0, 0, f"Game Over! Final Score: {self.score}")
        self.stdscr.refresh()
        curses.napms(2000)
        self.stdscr.clear()
        self.stdscr.refresh()

    def update(self, key):
        if key == curses.KEY_UP:
            self.spaceship.move("up")
        elif key == curses.KEY_DOWN:
            self.spaceship.move("down")
        elif key == curses.KEY_LEFT:
            self.spaceship.move("left")
        elif key == curses.KEY_RIGHT:
            self.spaceship.move("right")
        elif key == ord(" "):
            self.spaceship.shoot()

        for invader in self.invaders:
            invader.move()
            if invader.x == self.spaceship.x and invader.y == self.spaceship.y:
                self.end()
            for bullet in self.bullets:
                if bullet.x == invader.x and bullet.y == invader.y:
                    self.score += 1
                    self.invaders.remove(invader)
                    self.bullets.remove(bullet)

        self.stdscr.clear()
        self.stdscr.addstr(0, 0, f"Level: {self.level}")
        self.stdscr.addstr(1, 0, f"Score: {self.score}")
        self.spaceship.draw(self.stdscr)
        for invader in self.invaders:
            invader.draw(self.stdscr)
        for bullet in self.bullets:
            bullet.draw(self.stdscr)
        self.stdscr.refresh()

    def draw(self):
        self.stdscr.clear()
        self.stdscr.addstr(0, 0, f"Level: {self.level}")
        self.stdscr.addstr(1, 0, f"Score: {self.score}")
        self.spaceship.draw(self.stdscr)
        for invader in self.invaders:
            invader.draw(self.stdscr)
        for bullet in self.bullets:
            bullet.draw(self.stdscr)
        self.stdscr.refresh()

    def is_over(self):
        return not self.invaders
