import random

class Level:
    def __init__(self):
        self.difficulty = 1
        self.invaders_per_level = {
            1: 5,
            2: 10,
            3: 15,
            4: 20,
            5: 25,
            6: 30,
            7: 35,
            8: 40,
            9: 45,
            10: 50
        }

    def generate_invaders(self, level):
        invaders = []
        for _ in range(self.invaders_per_level[level]):
            x = random.randint(0, 79)
            y = random.randint(0, 19)
            invaders.append(Invader(x, y))
        return invaders

class Invader:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def move(self):
        self.y += 1

    def shoot(self):
        return Bullet(self.x, self.y)

class Bullet:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def move(self):
        self.y -= 1
```
