from django.shortcuts import render, redirect
from django.contrib.auth.decorators import login_required
from django.contrib import messages
from .models import Paper
from .forms import PaperForm

def submit_paper(request):
    """
    Submit a new paper.
    """
    if request.method == 'POST':
        form = PaperForm(request.POST)
        if form.is_valid():
            paper = form.save(commit=False)
            paper.author = request.user
            paper.save()
            messages.success(request, 'Paper submitted successfully!')
            return redirect('paper_list')
    else:
        form = PaperForm()
    return render(request, 'papers/submit_paper.html', {'form': form})

@login_required
def paper_list(request):
    """
    Display a list of papers.
    """
    papers = Paper.objects.all()
    return render(request, 'papers/paper_list.html', {'papers': papers})

@login_required
def paper_detail(request, pk):
    """
    Display the details of a paper.
    """
    paper = Paper.objects.get(pk=pk)
    return render(request, 'papers/paper_detail.html', {'paper': paper})

@login_required
def paper_update(request, pk):
    """
    Update a paper.
    """
    paper = Paper.objects.get(pk=pk)
    if request.method == 'POST':
        form = PaperForm(request.POST, instance=paper)
        if form.is_valid():
            form.save()
            messages.success(request, 'Paper updated successfully!')
            return redirect('paper_detail', pk=pk)
    else:
        form = PaperForm(instance=paper)
    return render(request, 'papers/paper_update.html', {'form': form})

@login_required
def paper_delete(request, pk):
    """
    Delete a paper.
    """
    paper = Paper.objects.get(pk=pk)
    if request.method == 'POST':
        paper.delete()
        messages.success(request, 'Paper deleted successfully!')
        return redirect('paper_list')
    return render(request, 'papers/paper_delete.html', {'paper': paper})
